public int bfsShortestPath(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    if (grid[0][0] == 1) return -1;
    Queue<int[]> queue = new LinkedList<>();
    boolean[][] visited = new boolean[m][n];
    queue.offer(new int[]{0, 0});
    visited[0][0] = true;
    int distance = 1;
    int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};

    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int[] curr = queue.poll();
            if (curr[0] == m - 1 && curr[1] == n - 1) return distance;
            for (int j = 0; j < 4; j++) {
                int nr = curr[0] + dr[j], nc = curr[1] + dc[j];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] == 0) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        distance++;
    }
    return -1;
}

public int minCost(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    int[] dist = new int[m * n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    Deque<int[]> dq = new ArrayDeque<>();
    dq.offerFirst(new int[]{0, 0}); // {node_index, cost}
    int[] dr = {0, 0, 1, -1}, dc = {1, -1, 0, 0};

    while (!dq.isEmpty()) {
        int[] curr = dq.pollFirst();
        int r = curr[0] / n, c = curr[0] % n;
        if (r == m - 1 && c == n - 1) return curr[1];
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                int newCost = curr[1] + (grid[r][c] == i + 1 ? 0 : 1);
                if (newCost < dist[nr * n + nc]) {
                    dist[nr * n + nc] = newCost;
                    if (grid[r][c] == i + 1) dq.offerFirst(new int[]{nr * n + nc, newCost});
                    else dq.offerLast(new int[]{nr * n + nc, newCost});
                }
            }
        }
    }
    return -1;
}

public int numIslands(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '1') {
                dfs(grid, i, j);
                count++;
            }
        }
    }
    return count;
}

private void dfs(char[][] grid, int r, int c) {
    if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length || grid[r][c] != '1') return;
    grid[r][c] = '0'; // Mark visited
    dfs(grid, r + 1, c);
    dfs(grid, r - 1, c);
    dfs(grid, r, c + 1);
    dfs(grid, r, c - 1);
}

public int[] findOrder(int numCourses, int[][] prerequisites) {
    List<List<Integer>> graph = new ArrayList<>();
    int[] indegree = new int[numCourses];
    for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
    for (int[] p : prerequisites) {
        graph.get(p[1]).add(p[0]);
        indegree[p[0]]++;
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < numCourses; i++) if (indegree[i] == 0) queue.offer(i);
    int[] order = new int[numCourses];
    int idx = 0;
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        order[idx++] = curr;
        for (int neighbor : graph.get(curr)) {
            if (--indegree[neighbor] == 0) queue.offer(neighbor);
        }
    }
    return idx == numCourses ? order : new int[]{};
}

class UnionFind {
    private int[] parent;
    private int[] rank;
    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    public int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    public boolean union(int x, int y) {
        int rootX = find(x), rootY = find(y);
        if (rootX == rootY) return false; 
        if (rank[rootX] < rank[rootY]) parent[rootX] = rootY;
        else if (rank[rootX] > rank[rootY]) parent[rootY] = rootX;
        else { parent[rootY] = rootX; rank[rootX]++; }
        return true;
    }
}

// Floyd-Warshall Algorithm
public int[][] floydWarshall(int n, int[][] edges) {
    int[][] dist = new int[n][n];
    for (int i = 0; i < n; i++) {
        Arrays.fill(dist[i], 10000000); // Use a large number instead of MAX_VALUE to avoid overflow
        dist[i][i] = 0;
    }
    for (int[] e : edges) {
        dist[e[0]][e[1]] = e[2];
        dist[e[1]][e[0]] = e[2]; // If undirected
    }
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }
    return dist;
}

// Prim's Algorithm
public int minCostConnectPoints(int[][] points) {
    int n = points.length, cost = 0, edgesUsed = 0;
    boolean[] visited = new boolean[n];
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
    pq.offer(new int[]{0, 0}); 

    while (edgesUsed < n) {
        int[] curr = pq.poll();
        int node = curr[0], weight = curr[1];
        if (visited[node]) continue;
        visited[node] = true;
        cost += weight;
        edgesUsed++;
        for (int next = 0; next < n; next++) {
            if (!visited[next]) {
                int dist = Math.abs(points[node][0] - points[next][0]) + Math.abs(points[node][1] - points[next][1]);
                pq.offer(new int[]{next, dist});
            }
        }
    }
    return cost;
}

private int time = 0;
public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
    for (List<Integer> conn : connections) {
        graph.get(conn.get(0)).add(conn.get(1));
        graph.get(conn.get(1)).add(conn.get(0));
    }
    List<List<Integer>> bridges = new ArrayList<>();
    int[] disc = new int[n], low = new int[n];
    Arrays.fill(disc, -1);
    for (int i = 0; i < n; i++) {
        if (disc[i] == -1) dfs(i, -1, disc, low, graph, bridges);
    }
    return bridges;
}
private void dfs(int u, int parent, int[] disc, int[] low, List<List<Integer>> graph, List<List<Integer>> bridges) {
    disc[u] = low[u] = time++;
    for (int v : graph.get(u)) {
        if (v == parent) continue;
        if (disc[v] == -1) {
            dfs(v, u, disc, low, graph, bridges);
            low[u] = Math.min(low[u], low[v]);
            if (low[v] > disc[u]) bridges.add(Arrays.asList(u, v));
        } else {
            low[u] = Math.min(low[u], disc[v]);
        }
    }
}

