}

public int minimumEffortPath(int[][] heights) {
    int left = 0, right = 1000000;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (canReachDestination(heights, mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}
private boolean canReachDestination(int[][] h, int maxEffort) {
    Queue<int[]> q = new LinkedList<>();
    q.offer(new int[]{0, 0});
    boolean[][] visited = new boolean[h.length][h[0].length];
    visited[0][0] = true;
    int[] dr = {0, 0, 1, -1}, dc = {1, -1, 0, 0};
    while (!q.isEmpty()) {
        int[] curr = q.poll();
        if (curr[0] == h.length - 1 && curr[1] == h[0].length - 1) return true;
        for (int i = 0; i < 4; i++) {
            int nr = curr[0] + dr[i], nc = curr[1] + dc[i];
            if (nr >= 0 && nr < h.length && nc >= 0 && nc < h[0].length && !visited[nr][nc]) {
                if (Math.abs(h[nr][nc] - h[curr[0]][curr[1]]) <= maxEffort) {
                    visited[nr][nc] = true;
                    q.offer(new int[]{nr, nc});
                }
            }
        }
    }
    return false;
}

// Shortest Path Visiting All Nodes (Bitmask DP + BFS)
public int shortestPathLength(int[][] graph) {
    int n = graph.length;
    int allVisited = (1 << n) - 1;
    Queue<int[]> queue = new LinkedList<>(); 
    boolean[][] visited = new boolean[n][1 << n];
    for (int i = 0; i < n; i++) {
        queue.offer(new int[]{i, 1 << i, 0});
        visited[i][1 << i] = true;
    }
    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int node = curr[0], mask = curr[1], dist = curr[2];
        if (mask == allVisited) return dist;
        for (int neighbor : graph[node]) {
            int newMask = mask | (1 << neighbor);
            if (!visited[neighbor][newMask]) {
                visited[neighbor][newMask] = true;
                queue.offer(new int[]{neighbor, newMask, dist + 1});
            }
        }
    }
    return -1;
}
